class Invoice:
    def __init__(self, currency, lines=()):
        self.currency = currency
        self._lines = list(lines)

    def add_line(self, line):                 # behaviour stays with the data
        if line.currency != self.currency: raise ValueError('currency mismatch')
        self._lines.append(line)

    @property
    def total(self): return sum(l.amount for l in self._lines)
